INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127721, 'spa', 'volverse, girar', 'Sentido físico primario de rotar el cuerpo o cambiar de dirección en el espacio, con 85 apariciones. Incluye a Moisés mirando a un lado y otro (Ex 2:12) y fuerzas militares que se volvieron para huir (Jue 20:45). Árabe الْتَفَتَ (volverse), coreano 돌아보았다 (se volvió) y suajili -geuka lo confirman de modo uniforme.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127722, 'spa', 'orientarse, mirar hacia', 'Orientación estática más que giro dinámico — describe hacia qué dirección mira o está posicionado algo. Se usa arquitectónicamente en las descripciones de linderos de Josué (''el lindero mira hacia...'') y para los utensilios del templo en 1 Reyes 7:25. Árabe distingue con مُتَّجِهَة (dirigido/orientado) y coreano con 향하는 (de cara a).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127729, 'spa', 'Piel: preparar, despejar', 'Forma intensiva Piel con sentido especializado de despejar, preparar o disponer — especialmente caminos o espacios. Célebre en Isaías 40:3 ''preparad camino al SEÑOR'' y Salmo 80:9 ''limpiaste terreno delante de ella (la vid)''. Árabe هَيِّئُوا (¡preparad!), coreano 예비하라 (¡preparad!), suajili -tayarisha (preparar).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127732, 'spa', 'Hifil: hacer volver', 'Forma causativa Hifil: hacer que algo o alguien se vuelva, o girar algo uno mismo. Incluye a Sansón atando antorchas a las colas de los zorros y soltándolos (Jue 15:4) y el cambio de corazón (1 S 10:9). Árabe أَدَارُوا (hicieron girar), coreano 돌렸다 (hizo girar) muestran la fuerza transitiva causativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127748, 'spa', 'giro del tiempo', 'Uso temporal: el infinitivo constructo con preposición expresa ''al caer'' o ''al declinar'' de la tarde, la mañana o el día. Marca transiciones entre períodos temporales. Se encuentra en Génesis 24:63 ''al caer la tarde'' y Éxodo 14:27 ''a la vigilia de la mañana''. Árabe عِنْدَ إِقْبَالِ (a la llegada de).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127753, 'spa', 'declinar, pasar', 'Declinar temporal o figurativo, desvanecerse o menguar. Árabe cambia a فَنَتْ (pereció) y مَالَ (declinó) — raíces distintas del verbo básico ''volverse'', indicando polisemia genuina reconocida interlingüísticamente. Describe el día que declina (Jr 6:4) y los años que pasan como un relato (Sal 90:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127769, 'spa', 'mirar, prestar atención', 'Extensión a la atención mental: volver la mirada o el enfoque hacia alguien, implicando consideración. Solo 3 casos claros: Éxodo 2:12 (Moisés miró a uno y otro lado), Salmo 102:17 (atiende a la oración) y Hageo 1:9 (esperabais mucho). Hindi usa देखा (vio) y suajili -angalia (mirar).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127773, 'spa', 'apartar, retirar', 'Aparición única e incierta en Sofonías 3:15: ''ha apartado (el juicio)'' — posiblemente un sentido de remoción o reversión, pero demasiado aislado para caracterizarlo con certeza. Árabe ha-apartado sugiere un significado de retirar distinto del giro espacial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127783, 'spa', 'vaciar', 'Aparición anómala única en Levítico 14:36: ''vaciarán (la casa)'' antes de que el sacerdote la examine por lepra. Este uso puede pertenecer a una raíz diferente o representar un término técnico levítico que se aisló de la semántica central de volverse.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127797, 'spa', 'esquina', 'Término arquitectónico único en 2 Crónicas 25:23, traducido como ''la (puerta de la) Esquina'' — el lugar donde un muro gira. Posible uso sustantivado del participio: ''el punto de giro'', donde la dirección cambia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127799, 'spa', 'La esquina o ángulo físico de un edificio, altar, muralla, techo o calle', 'La esquina o ángulo físico de un edificio, altar, muralla, techo o calle. Se usa 22 veces en Éxodo, Reyes, Crónicas, Nehemías, Ezequiel y Proverbios para designar el punto de giro espacial de un objeto construido o un elemento urbano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127801, 'spa', 'Extensión figurada donde ''esquinas'' designa jefes, líderes o personas principale', 'Extensión figurada donde ''esquinas'' designa jefes, líderes o personas principales de la comunidad. En Jueces 20:2 y 1 Samuel 14:38, פִּנּוֹת הָעָם (''esquinas del pueblo'') identifica a los gobernantes alrededor de quienes se estructura la nación, así como las piedras angulares sostienen un edificio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127806, 'spa', 'La piedra angular o piedra principal de fundamento (אֶבֶן פִּנָּה), usada tanto ', 'La piedra angular o piedra principal de fundamento (אֶבֶן פִּנָּה), usada tanto literalmente en arquitectura como metafóricamente de los propósitos creativos y redentores de Dios. Job 38:6 pregunta quién puso la piedra angular de la tierra; Isaías 28:16 promete una piedra probada en Sion; Salmo 118:22 declara que la piedra desechada vino a ser la cabeza del ángulo — pasaje que el Nuevo Testamento aplica directamente a Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127816, 'spa', 'Penuel / Peniel (nombre propio)', 'El nombre propio Penuel/Peniel (פְּנוּאֵל / פְּנִיאֵל), que significa ''rostro de Dios''. Principalmente un topónimo del lugar al este del Jordán, cerca del Jaboc, donde Jacob luchó con el ser divino y lo llamó así ''porque he visto a Dios cara a cara'' (Gn 32:30–31). La localidad reaparece en la campaña de Gedeón contra Madián (Jue 8:8–9, 17) y como ciudad fortificada por Jeroboam (1 R 12:25). Dos individuos también llevan este nombre en las genealogías.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127821, 'spa', 'ante, enfrente de (espacial)', 'El rostro o presencia del Señor, con mayor frecuencia en la expresión ''delante de YHWH'' (liphnê YHWH). Este uso teológico subraya la presencia y accesibilidad divinas en el culto. Las glosas multilingües mantienen el giro preposicional (español delante de, árabe أَمَامَ الرَّبِّ, suajili mbele za Bwana).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127832, 'spa', 'cara, orientación frontal', 'Orientación o posición espacial: ''enfrente'', ''de cara a'', ''frente a''. La evidencia interlingüística muestra vocabulario direccional consistente (español delante, francés devant, chino 面前), distinguiendo este sentido físico-espacial del sentido teológico de presencia divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127850, 'spa', 'antes de, previamente', 'El rostro físico literal de un ser humano o animal. Las glosas emplean vocabulario anatómico facial (español rostro/cara, árabe وَجْهَ, hindi मुँह), identificando claramente este como el sentido corporal concreto, diferenciado de las extensiones metafóricas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127873, 'spa', 'a causa de, por razón de', 'Sentido causal: ''a causa de'', ''por motivo de'', ''debido a''. Frecuente en contextos donde la presencia o acción de alguien provoca una consecuencia. Las traducciones emplean locuciones causales (español por causa de, a causa de), reflejando una extensión semántica desde la confrontación espacial hacia la motivación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127901, 'spa', 'superficie, faz de', 'La superficie o faz de la tierra, el suelo o las aguas. Esta extensión del rostro humano a la superficie terrestre se refleja en traducciones que mantienen la construcción ''faz de'' (árabe وَجْهِ الأَرْضِ, suajili uso wa nchi) o recurren a terminología de ''superficie''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127928, 'spa', 'Adentro, hacia el interior', 'Adverbio direccional que significa ''adentro, hacia el interior'', formado a partir de פָּנִים (''rostro'') con el sufijo locativo he — literalmente ''hacia el rostro'' desde la entrada. Usado predominantemente en contextos del templo de Salomón (1 Re 6:18, 19, 21, 30) y el templo visionario de Ezequiel (Ez 40:16; 41:3). Con לְ indica movimiento hacia el interior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127934, 'spa', 'Adjetivo que designa la parte interior de un edificio sagrado o real, siempre us', 'Adjetivo que designa la parte interior de un edificio sagrado o real, siempre usado con el artículo definido. En el templo de Salomón marca el atrio interior y las cámaras internas (1 R 6:27, 36; 7:12, 50). En Ezequiel 40-46 domina la visión del templo, especificando puertas interiores, atrios interiores y salas internas como indicadores espaciales de santidad creciente. El término traza la arquitectura sagrada en zonas concéntricas de acceso progresivo hacia la presencia divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127937, 'spa', 'Piedras preciosas', 'Gemas de valor excepcional, posiblemente corales rojos, perlas o rubíes (identificación incierta). El cognado árabe fanan (''rama'') favorece la interpretación como coral. Casi todas las apariciones son comparativas: la sabiduría las supera (Pr 3:15; 8:11), la mujer virtuosa las excede (Pr 31:10), y no compran la sabiduría verdadera (Job 28:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127942, 'spa', 'Nombre personal', 'Nombre personal de la esposa de Elcana y rival de Ana. 1 Samuel 1:2 presenta el hogar: ''Tenía dos esposas. El nombre de una era Ana, y el de la otra Peniná (פְּנִנָּה). Y Peniná (וְלִפְנִנָּה) tenía hijos, pero Ana no tenía hijos.'' El versículo 4 menciona las porciones del sacrificio de Elcana: ''a Peniná (וְלִפְנִנָּה) su esposa y a todos sus hijos e hijas les dio porciones.'' Su rol como provocadora resalta el dolor de Ana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127943, 'spa', 'Mimar con exceso', 'Participio Piel en Proverbios 29:21 que describe a quien mima o consiente a un siervo, tratándolo con excesiva indulgencia desde la juventud. El término sugiere la eliminación de límites apropiados y de la disciplina, permitiendo una familiaridad indebida. El proverbio advierte que este enfoque resulta contraproducente: el siervo se vuelve presuntuoso, llegando quizás a esperar derechos de herencia. El verbo captura el lado problemático de la permisividad excesiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127944, 'spa', 'Tunica hasta las extremidades', 'Palma de la mano o planta del pie, usado exclusivamente en la frase ketonet passim para describir una tunica que se extiende hasta las extremidades, prenda de distincion. Entregada por Jacob a Jose como senal de favor (Gen 37:3, 23, 32) y usada por las princesas virgenes (2 Sam 13:18-19). La conocida traduccion ''de muchos colores'' refleja la tradicion versional antigua, pero el hebreo indica una vestidura larga de rango especial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127946, 'spa', 'Atravesar y examinar', 'Verbo imperativo en el Salmo 48:13 (textualmente incierto), que aparentemente significa ''atravesar'' o ''pasar entre'', refiriéndose a los palacios de Jerusalén. Forma parte de un llamado litúrgico a circundar y observar cuidadosamente las fortificaciones de Sion, sugiriendo un recorrido deliberado entre las estructuras para examinarlas de cerca. El salmo invita a los adoradores a meditar en la fortaleza de la ciudad como testimonio de la protección de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127947, 'spa', 'Pisga', 'Cresta montañosa en Moab al noreste del mar Muerto, usada siempre con artículo definido. Moisés contempló desde su cumbre la Tierra Prometida antes de morir (Dt 3:27; 34:1), y Balac llevó allí a Balaam (Nm 23:14). Las «vertientes de Pisga» servían como marcadores fronterizos (Dt 3:17; 4:49; Jos 12:3; 13:20).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127948, 'spa', 'Topónimo bélico', 'Nombre de lugar en 1 Crónicas 11:13 que identifica un sitio de batalla en el occidente de Judá, donde uno de los guerreros de élite de David defendió un campo contra los filisteos. El nombre, que significa aproximadamente ''límite de sangre'', refleja la historia violenta de esta zona fronteriza disputada entre israelitas y filisteos. Ubicado cerca de Soco y Azeca, Pas-damim fue escenario de múltiples enfrentamientos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127949, 'spa', 'Abundancia desbordante', 'Término textualmente incierto en el Salmo 72:16, que aparentemente significa ''abundancia'' o ''puñado'', referido al grano durante el reinado del rey mesiánico. La imagen evoca tal fertilidad agrícola que incluso las cumbres de los montes, normalmente inadecuadas para el cultivo, producen en abundancia. Ya sea que el vocablo designe un puñado literal o una abundancia simbólica, el contexto señala claramente una fertilidad extraordinaria como signo de bendición divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127950, 'spa', 'Pasar por encima', 'Pasar por encima y perdonar, especialmente en la liberación pascual. Éxodo 12:13, 23, 27 narran la promesa y el cumplimiento divinos: pasar por encima de las casas israelitas marcadas con sangre mientras hería a los primogénitos egipcios. Isaías 31:5 aplica la imagen a la protección de Jerusalén. Los cuatro usos describen el perdón selectivo divino: Dios «pasa por encima» para proteger a su pueblo mientras juzga a sus opresores.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127951, 'spa', 'Cojear o renquear', 'La palabra aparece en contextos tanto literales (la cojera de Mefiboset por lesión en 2 Sam 4:4) como metafóricos (titubear entre dos opiniones en 1 Re 18:21). La danza de los profetas de Baal en 1 Re 18:26 puede ser cojera literal como parte de un ritual. Las traducciones al español (cojeáis, cojeó) y al francés (boitant) confirman el sentido de discapacidad física en todos los contextos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127952, 'spa', 'Pascua (festividad) — La festividad de la Pascua en su conjunto, que conmemora e', 'Pascua (festividad) — La festividad de la Pascua en su conjunto, que conmemora el éxodo de Israel de Egipto y se celebra anualmente el catorce de Nisán. Este sentido dominante (45 de 49 apariciones) abarca el relato de institución en Éxodo 12, la observancia en el desierto en Números 9 y las grandes reformas bajo Josías (2 R 23:21-23). Las traducciones la rinden uniformemente como nombre propio de festividad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127955, 'spa', 'Ofrenda/cordero pascual — El animal sacrificial —un cordero o cabrito— sacrifica', 'Ofrenda/cordero pascual — El animal sacrificial —un cordero o cabrito— sacrificado para la cena pascual, una extensión metonímica de la festividad a su ofrenda central. Este sentido emerge claramente en 2 Cr 30:17 y 35:7-9, donde los levitas sacrifican «los pesajim» (plural) por millares y los líderes distribuyen rebaños para este propósito. Es el sentido concreto y contable del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127961, 'spa', 'Nombre propio', 'Aunque la clasificación de dominio sugiere ''Festividades'' (quizá confundiéndolo con פֶּסַח, ''Pascua''), las glosas lo identifican claramente como un nombre propio (Pasea). Las transliteraciones en inglés, español y francés lo tratan uniformemente como nombre de persona. Los tres individuos son personas distintas que comparten el mismo nombre a lo largo de diferentes generaciones y contextos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127962, 'spa', 'Cojo — Físicamente incapaz de caminar correctamente debido a una lesión o deform', 'Cojo — Físicamente incapaz de caminar correctamente debido a una lesión o deformidad en las piernas o los pies. El emparejamiento constante con עִוֵּר (''ciego'') a lo largo de la poesía y la ley hebrea — reflejado por el español cojo/ciego y el francés boiteux/aveugle — lo marca como la abreviatura bíblica principal para la discapacidad corporal. Se aplica a personas (2 Sam 9:13, ''cojo de ambos pies'') y a animales sacrificiales (Deut 15:21). La inversión profética promete que el cojo saltará como un ciervo (Isa 35:6) y será reunido por Dios (Jer 31:8), transformando el estigma en esperanza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127969, 'spa', 'Imágenes talladas o grabadas usadas en adoración idolátrica, fabricadas en mader', 'Imágenes talladas o grabadas usadas en adoración idolátrica, fabricadas en madera (Deuteronomio 7:5, 25), piedra (Isaías 21:9) o metal recubierto de plata (Isaías 30:22). Deuteronomio prescribe su destrucción (7:5, 25; 12:3), los profetas condenan la devoción a ellas (Oseas 11:2; Miqueas 5:13), y la reforma de Josías las tomó como objetivo (2 Crónicas 34:3-7). Enfatizan objetos físicamente moldeados por manos humanas pero vanamente venerados como divinos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127988, 'spa', 'Nombre personal aserita', 'Nombre propio en 1 Crónicas 7:33 que identifica a un descendiente de Aser por la línea de Jaflet. Pasac representa un eslabón en la genealogía tribal de Aser, preservado en la documentación exhaustiva de las estructuras familiares de Israel que realiza el Cronista. Aunque no protagoniza acciones en el relato bíblico, su inclusión mantiene el registro de las familias aseritas como parte del proyecto de afirmar la continuidad de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127989, 'spa', 'Labrar, tallar', 'Labrar o tallar piedra o madera para darle la forma deseada, usado en el tronco Qal. El contexto principal es Moisés cortando tablas de piedra de reemplazo por mandato de Dios (Éx 34:1, 4; Dt 10:1, 3), mientras que 1 R 5:18 lo extiende a la extracción de piedras para el Templo de Salomón. Hab 2:18 lo aplica a la fabricación de un ídolo, empleando el acusativo cognado con pesel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (127995, 'spa', 'Imagen física tallada en madera, piedra o fundida en metal, que sirve como objet', 'Imagen física tallada en madera, piedra o fundida en metal, que sirve como objeto de culto ilícito. Prohibida en el Decálogo (Éx 20:4; Dt 5:8) y en las maldiciones del pacto (Dt 27:15). El relato de Micaía ilustra la fabricación doméstica de ídolos y su robo por los danitas (Jue 17:3-4; 18:14-31). La sátira del taller de Isaías muestra un solo tronco repartido entre leña y divinidad (Is 40:19-20; 44:9-17). Jeremías y Nahúm pronuncian juicio sobre quienes fabrican imágenes talladas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128010, 'spa', 'Instrumento de cuerdas', 'Las cuatro apariciones se encuentran en Dan 3:5, 7, 10, 15 dentro de la fórmula repetida que enumera la orquesta de Nabucodonosor. El inglés ''harp'', el español ''salterio'' y el francés ''harpe'' lo identifican como instrumento de cuerdas. La leve variación ortográfica (פְּסַנְטֵרִין frente a פְּסַנְתֵּרִין) refleja la flexibilidad ortográfica típica del arameo para préstamos extranjeros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128011, 'spa', 'Desaparición completa', 'Verbo en Qal perfecto en el Salmo 12:1 que describe a los fieles como habiendo desaparecido o desvanecido de entre la humanidad. El término transmite más que una disminución numérica: sugiere una desaparición total, como si los piadosos hubieran sido disueltos o borrados de la existencia. El lamento del salmista emplea este verbo contundente para expresar su profundo aislamiento al no encontrar a nadie comprometido con la fidelidad a la alianza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128012, 'spa', 'Nombre personal aserita', 'Nombre propio en 1 Crónicas 7:38 que identifica a un descendiente de Aser por la línea de Jeter. Pispa no posee narrativa individual, sino que forma parte de la documentación sistemática del Cronista sobre las genealogías tribales. Su inclusión contribuye a establecer la integridad de los registros familiares de Aser, dentro del proyecto mayor de demostrar la continuidad y legitimidad de todas las tribus de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128013, 'spa', 'Gemir con esfuerzo', 'Verbo en Isaías 42:14 donde Dios dice «gemiré como mujer de parto», empleando la imagen del alumbramiento para describir su intervención a favor de Israel. El término onomatopéyico capta sonidos involuntarios de esfuerzo intenso, no de debilidad sino de exerción poderosa. Tras una larga contención, Dios se entregará al trabajo de liberar a su pueblo, expresando así el carácter costoso y laborioso de la redención.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128015, 'spa', 'Monte y deidad moabita', 'Un monte en Moab y su deidad asociada. Como toponimo, designa la altura donde Balaam pronuncio su oraculo contemplando el desierto (Num 23:28). Como nombre divino, se refiere al dios moabita/madianita cuyo culto provoco la catastrofica apostasia de Israel (Num 25:18; 31:16), evento recordado como precedente de advertencia (Jos 22:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128016, 'spa', 'Hacedor u obrador de — El que hace u obra', 'Hacedor u obrador de — El que hace u obra: el participio sustantivado que aparece 24 veces, abrumadoramente en la frase fija פֹּעֲלֵי אָוֶן («obradores de iniquidad»). Esta construcción domina los Salmos como designación de los impíos: «los jactanciosos no estarán delante de tus ojos; aborreces a todos los que obran iniquidad» (Sal 5:5), «apartaos de mí, todos los que obráis maldad» (Sal 6:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128017, 'spa', 'Hacer o realizar — Hacer, realizar o llevar a cabo una acción', 'Hacer o realizar — Hacer, realizar o llevar a cabo una acción: el sentido verbal general con 23 apariciones, que abarca la conducta moral, la acción divina y las obras humanas. En Números 23:23, Balaam declara «¡lo que ha hecho Dios!», y Deuteronomio 32:27 advierte que los enemigos no digan «nuestra mano ha hecho esto». Los diálogos de Job emplean repetidamente el verbo para la acción divina cuyo sentido es inescrutable (Job 11:8; 22:17; 33:29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128022, 'spa', 'Hacer o formar — Hacer, formar o crear', 'Hacer o formar — Hacer, formar o crear: 8 apariciones donde el verbo adquiere un significado creativo o constructivo, a menudo con Dios como sujeto. Éxodo 15:17 celebra el santuario que «tus manos, oh Señor, han hecho»; Job 36:3 declara «atribuiré justicia a mi Hacedor»; y Salmo 7:13-15 describe a Dios como quien «forja» armas de juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128029, 'spa', 'Trabajar (uso artesanal incierto) — Uso incierto o transicional', 'Trabajar (uso artesanal incierto) — Uso incierto o transicional: una sola aparición en Isaías 44:12, donde el herrero «trabaja» el hierro con tenazas sobre las brasas. El contexto de labor artesanal podría encajar tanto en el sentido 2 (realizar una acción) como en el 3 (formar algo). El enfoque del versículo en la artesanía metalúrgica podría justificar un sentido separado de trabajo manual especializado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128054, 'spa', 'El sentido dominante', 'El sentido dominante: obra o acción realizada por Dios o por los seres humanos, sujeta a evaluación moral. Deuteronomio 32:4 celebra la «obra» de Dios como perfecta; Salmo 44:1 recuerda el testimonio ancestral de la «obra» divina; Rut 2:12 lo aplica a la conducta humana valerosa. Se centra en la acción deliberada y sus resultados perdurables.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128075, 'spa', 'Extensión metonímica de la labor realizada a la compensación debida', 'Extensión metonímica de la labor realizada a la compensación debida: salario o retribución. Job 7:2 compara al que sufre con un jornalero que «espera su salario»; Jeremías 22:13 denuncia al rey que retiene la paga del prójimo. El registro económico marca un desplazamiento claro respecto de la «obra» valorativa del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128081, 'spa', 'Una ocurrencia aislada e incierta en Proverbios 21', 'Una ocurrencia aislada e incierta en Proverbios 21:6, en relación con «obtener tesoros con lengua mentirosa». El sentido puede inclinarse hacia la ganancia ilícita o el producto de un esfuerzo engañoso, aunque los léxicos dejan abierto el significado preciso. Es una acepción liminal entre «obra» y «salario».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128083, 'spa', 'Salario, recompensa, retribución — el pago recibido por el trabajo o la retribuc', 'Salario, recompensa, retribución — el pago recibido por el trabajo o la retribución debida por las acciones propias. Levítico 19:13 lo usa concretamente para el salario del jornalero que no debe retenerse. Isaías 40:10 y 62:11 lo emplean para la recompensa divina, con la pe''ullah de Dios llegando ante Él como botín de victoria. El Salmo 109:20 lo aplica como retribución contra los enemigos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128085, 'spa', 'Obra, acción, labor — el trabajo o esfuerzo en sí mismo, más que su pago', 'Obra, acción, labor — el trabajo o esfuerzo en sí mismo, más que su pago. El Salmo 28:5 invoca las ''obras de las manos del Señor'', y el Salmo 17:4 hace referencia a las ''acciones'' humanas en el contexto de la conducta moral. Proverbios 10:16 empareja el salario del justo con el producto (tevu''ah) del malvado, difuminando la línea entre acción y resultado. Jeremías 31:16 promete que la ''obra'' de Raquel — su sufrimiento y duelo — tendrá recompensa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128095, 'spa', 'Portero levita', 'Nombre propio en 1 Crónicas 26:5 que identifica a uno de los hijos de Obed-edom, quien servía como portero levítico del templo durante la organización del culto por David. La familia de Peultai recibió una bendición divina especial vinculada al cuidado del arca, bendición que se extendió a su servicio continuo como guardianes de las puertas del santuario y custodios del orden sagrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128096, 'spa', 'Impulsar o turbar', 'Empujar, impulsar o agitar, y en las formas reflexivas/pasivas, estar profundamente turbado o perturbado en espiritu. El Qal describe la impulsion divina de Sanson por el Espiritu (Jue 13:25). El Nifal/Hitpael expresan perturbacion psicologica: el espiritu turbado de Faraon tras sus suenos (Gen 41:8), el desvelo agitado de Nabucodonosor (Dan 2:1, 3) y la angustia inquieta del salmista (Sal 77:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128097, 'spa', 'vez, ocasión', 'Una vez u ocasión de ocurrencia — la acepción dominante con 101 apariciones, usada en frases de conteo y expresiones temporales. En Génesis 2:23 Adán exclama ''esta vez'' (הַפַּעַם) al ver a Eva — la primera aparición de la palabra en las Escrituras marca el primer acto de reconocimiento humano. El dual פַּעֲמַיִם significa ''dos veces'' (Gn 27:36, Esaú lamenta: ''ya me ha suplantado dos veces'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128106, 'spa', 'pie, base', 'El pie físico o la base/esquina de un objeto — 7 apariciones que abarcan anatomía humana y mobiliario sagrado. En Éxodo 25:12 y 37:3 el arca de la alianza tiene cuatro פַּעֲמֹת (''pies/esquinas'') para sus argollas de transporte; en 1 Reyes 7:30 las basas de bronce del templo de Salomón tienen פַּעֲמֹת como estructuras de soporte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128108, 'spa', 'paso, pisada', 'Un paso, pisada o el sonido de pasos — 9 apariciones concentradas en textos poéticos y proféticos. En Jueces 5:28 la madre de Sísara mira por la celosía preguntando ''¿por qué tardan los cascos (פַּעֲמֵי) de sus carros?'' — uno de los momentos más sobrecogedores de la poesía bíblica, donde la palabra capta la percusión rítmica de los caballos que se acercan. En Salmo 85:13 la justicia ''irá delante de él y pondrá sus pasos en el camino''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128111, 'spa', 'yunque', 'Un yunque — única aparición en Isaías 41:7, donde el profeta describe la fabricación de un ídolo: el artesano anima al metalúrgico, y el que alisa con el martillo golpea ''el yunque'' (פָּעַם). La conexión con el significado raíz es elegante: el yunque es aquello que recibe ''golpes'' repetidos, retornando a la etimología percusiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128129, 'spa', 'Campanilla sacerdotal', 'Pequeña campana ornamental dorada sujeta al borde de la túnica del sumo sacerdote, alternando con decoraciones de granada. Deriva de pa''am (''golpear''), aludiendo al badajo. Éxodo prescribe «una campanilla de oro y una granada» en alternancia (Éx 28:33-34); su sonido anunciaba la entrada del sacerdote al Lugar Santo (Éx 28:35).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128134, 'spa', 'Abrir la boca', 'Job 16:10 retrata a los enemigos abriendo la boca en burla. Job 29:23 muestra al pueblo abriendo ávidamente la boca ante la sabiduría de Job, como tierra sedienta ante la lluvia. Salmo 119:131 expresa hambre espiritual: ''Abrí mi boca y jadeé, porque anhelaba tus mandamientos''. Isaías 5:14 personifica al Seol abriéndose sin medida. La imagen constante en todos los idiomas es una boca abierta de par en par.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128135, 'spa', 'Guerrero valiente davídico', 'Nombre propio en 2 Samuel 23:35 que identifica a uno de los «valientes» de David, los guerreros de élite que formaban su guardia personal y se destacaban por hazañas extraordinarias en combate. Designado «el arbita», Paarai provenía probablemente de la región de la Arabá. Su presencia en esta selecta lista conmemoró de forma permanente su valor y lealtad a David. El texto paralelo de 1 Crónicas registra una variante del nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128136, 'spa', 'Rescatar o liberar — ''abrir'' se convierte en ''soltar del cautiverio''', 'Rescatar o liberar — ''abrir'' se convierte en ''soltar del cautiverio''. Las tres ocurrencias aparecen en el Salmo 144: ''Rescátame de la mano de los extranjeros'' (vv. 7, 11) y ''el que rescata a David'' (v. 10). El cognado arameo petsa (''liberar'') y el árabe fasaya (''separar'') iluminan el puente semántico de abrir a liberación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128137, 'spa', 'Abrir la boca de par en par — la tierra se abre para tragar la sangre de Abel (G', 'Abrir la boca de par en par — la tierra se abre para tragar la sangre de Abel (Gn 4:11) o a los rebeldes de Coré (Nm 16:30; Dt 11:6), los enemigos abren sus bocas en burla hostil (Lm 2:16; Sal 22:14), y la hija de Jefté señala que su padre ''abrió su boca'' en un voto (Jue 11:35-36). El español abre y el francés ouvrir emplean verbos estándar de apertura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128146, 'spa', 'Abrir la boca para hablar — una única ocurrencia en el Salmo 66', 'Abrir la boca para hablar — una única ocurrencia en el Salmo 66:14: ''que mis labios abrieron'', refiriéndose a votos pronunciados en la angustia. La distinción con el sentido 1 es funcional: aquí la boca se abre para producir palabras, no para tragar o amenazar. La rareza sugiere que el hebreo prefería otros verbos como patach para este significado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128148, 'spa', 'Prorrumpir en canto/gozo', 'Qal: prorrumpir o estallar en canto gozoso y exultación ante YHWH. Se encuentra casi exclusivamente en las profecías de restauración de Isaías (Isa 14:7; 44:23; 49:13; 52:9; 54:1) y el Salmo 98:4. A menudo acompañado de רִנָּה (''grito de júbilo''), la expresión evoca una celebración corporativa irreprimible, un gozo que no puede contenerse.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128154, 'spa', 'Quebrar, triturar', 'Piel intensivo: quebrar o triturar físicamente, referido específicamente a destrozar huesos. En Miqueas 3:3, la acusación profética contra los líderes de Israel los describe despedazando al pueblo y ''quebrando sus huesos'', una imagen visceral de explotación. Única ocurrencia, pero la intensificación del Piel sobre la semántica de ''estallar/quebrar'' es clara.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128156, 'spa', 'Tarifa o precio incierto', 'La única aparición en 1 Samuel 13:21 se da en un contexto que trata sobre el control filisteo de la metalurgia y las tarifas cobradas a los israelitas por el mantenimiento de herramientas. Las glosas interlingüísticas apuntan consistentemente hacia terminología económica (cargo, precio), aunque el hebreo subyacente sigue siendo textualmente problemático. La erudición moderna generalmente reconoce que el pasaje requiere enmienda para una comprensión confiable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128158, 'spa', 'Descortezaduras visibles', 'En Génesis 30:37 este término aparece en una construcción con acusativo cognado que significa «peladuras blancas», describiendo el resultado de la remoción deliberada de corteza por parte de Jacob. Las glosas multilingües (peelings, descortezaduras, Schälungen) enfatizan de modo uniforme la naturaleza pelada de estas marcas. Esta técnica de manipulación agrícola se creía capaz de influir en las características de las crías en el mundo antiguo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128159, 'spa', 'Hender la tierra', 'En el Salmo 60:2, el salmista se dirige directamente a Dios: «La has hendido», refiriéndose a la tierra. El contexto describe una crisis nacional mediante imágenes de terremoto: Dios sacude la tierra, la hace abrirse y el pueblo tambalea. Las glosas multilingües (torn, partiste, zerrissen, ouvrir) captan de modo uniforme la acción de ruptura violenta, situando el término dentro del lenguaje de lamento ante el juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128160, 'spa', 'herir por contusión', 'Denota herir mediante magullamiento, aplastamiento o golpe con fuerza contundente. Deuteronomio 23:1 (versículo 2 en hebreo) excluye al ''herido por aplastamiento'' (פְּצוּעַ־דַּכָּה) de la asamblea—probablemente lesión genital. 1 Reyes 20:37 tiene al profeta solicitando: ''Golpéame y hiéreme (וּפָצֹעַ)''—necesitando lesión visible para su señal profética. El infinitivo absoluto enfatiza la acción. Cantar de los Cantares 5:7 describe a los guardias golpeándola violentamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128161, 'spa', 'Herida, lesión, contusión', 'Herida, contusión o lesión infligida por un golpe o acto violento. En los textos legales define el alcance del daño corporal que requiere compensación proporcional: ''herida por herida'' (Éx 21:25). El canto vengativo de Lamec la emplea para una herida mortal (Gn 4:23). La literatura sapiencial explora su complejidad moral: Proverbios 20:30 enseña que los golpes que hieren limpian el mal, mientras que Proverbios 27:6 afirma que las heridas de un amigo son fieles.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128167, 'spa', 'Nombre sacerdotal', 'En 1 Crónicas 24:15, Hapises figura entre los jefes de familias sacerdotales elegidos por sorteo para servir en turnos rotativos en el templo. Las glosas multilingües preservan el nombre propio con ligeras variaciones de transliteración. Este sistema de turnos sacerdotales, atribuido a la organización davídica, estructuró el culto del templo durante la monarquía y el período del Segundo Templo, sirviendo cada turno dos veces al año.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128168, 'spa', 'Instar, presionar', 'Presionar, instar o insistir ante alguien, ejerciendo presión social para que acepte hospitalidad, un regalo o una petición. Las seis ocurrencias en Qal involucran insistencia interpersonal: Lot instando urgentemente a los ángeles a alojarse con él (Gn 19:3), los hombres de Sodoma empujando físicamente a Lot (Gn 19:9), Jacob insistiendo en que Esaú acepte su presente (Gn 33:11) y los profetas presionando a Eliseo (2 R 2:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128174, 'spa', 'Obstinación, presunción', 'Uso nominal abstracto derivado del infinitivo absoluto Hifil, que denota obstinación presuntuosa o insistencia arrogante — una disposición más que una acción. Samuel la empareja con la rebelión (מְרִי) en 1 S 15:23: ''la obstinación es como idolatría''. Donde el sentido 1 describe un acto de insistencia entre personas, este sentido señala una actitud endurecida y desafiante contra la voluntad divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128175, 'spa', 'Depositado en custodia', 'En Levítico 6:4 esta forma aparece en una lista de delitos contra la propiedad: bienes robados, objetos extorsionados, cosas halladas y «lo que le fue depositado». Las glosas multilingües (deposited, depositado) captan el sentido de algo puesto en confianza. Esta categoría legal aborda la violación del deber fiduciario, cuando alguien hace uso indebido de propiedad explícitamente confiada a su cuidado, distinguiéndolo del robo directo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128176, 'spa', 'los contados, empadronados', 'El participio pasivo Qal usado sustantivamente (76x) domina los censos de Números: ''sus contados'' (Nm 1:21, 23, 25, 27, 29), refiriéndose a los inscritos en el censo militar de Israel. Árabe الْمَعْدُودُونَ (los contados), coreano 계수된 자들 (los censados). La construcción participial marca el estatus de haber sido enumerado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128177, 'spa', 'castigar, juzgar', 'Visitar con castigo o traer juicio (63x) describe la visitación divina negativa. ''Yo el SEÑOR visito la iniquidad de los padres sobre los hijos'' (Ex 20:5; 34:7; Dt 5:9), ''castigaré a Amalec'' (1 S 15:2). Árabe cambia a عَاقَبَ (castigar — raíz completamente diferente ع-ق-ب), coreano 벌하다 (castigar). La atención es hostil en este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128181, 'spa', 'contar, pasar revista', 'Contar, numerar o pasar revista (39x) aparece extensamente en Números. ''Haz un censo del pueblo de Israel'' (Ex 30:12), ''Moisés los contó según la palabra del SEÑOR'' (Nm 1:19). Árabe عَدَّ (contar) / أَحْصَى (enumerar), coreano 세다/계수하다 (contar). El sentido censal: atender a cada persona mediante enumeración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128183, 'spa', 'Hifil: nombrar, poner a cargo', 'Causativo Hifil ''nombrar, poner a cargo'' (23x) instala a alguien en autoridad. Potifar ''puso a José sobre su casa'' (Gn 39:4-5), Faraón ''nombró funcionarios sobre la tierra'' (Gn 41:34), Moisés ''puso a los levitas sobre el tabernáculo'' (Nm 1:50). Árabe عَيَّنَ (nombrar) / أَقَامَ (establecer), coreano 임명하다 (nombrar).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128184, 'spa', 'Hitpael: ser contado', 'Hitpael reflexivo ''ser contado, ser inscrito'' (8x) marca la participación pasiva en un censo. ''Pero los levitas no fueron contados entre el pueblo de Israel'' (Nm 1:47; 2:33; 26:62), ''Benjamín fue contado'' (Jue 20:15). Árabe يُعَدّ (pasivo de contar), coreano 세어지다 (ser contado). El Hitpael reflexivo sugiere participación voluntaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128191, 'spa', 'visitar, atender, cuidar', 'Visitar con atención graciosa o solicitud (32x) marca la visitación divina positiva. ''El SEÑOR visitó a Sara como había dicho'' (Gn 21:1), José dice a sus hermanos ''Dios ciertamente os visitará y os hará subir de esta tierra'' (Gn 50:24-25). Árabe افْتَقَدَ (visitar con solicitud, recordar), coreano 돌보다 (cuidar).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128198, 'spa', 'Hofal: los designados', 'Hofal pasivo ''los designados'' (7x) se refiere a los puestos a cargo (pasivo del Hifil #5). ''El dinero fue dado a los obreros designados'' (2 R 12:11; 22:5, 9; 2 Cr 34:10, 12). Árabe الْمُوَكَّلِينَ (los comisionados), coreano 임명된 자들 (los designados). El participio Hofal marca el estatus de haber sido nombrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128200, 'spa', 'Qal: designar, encomendar', 'Qal ''designar, poner sobre, encomendar'' (12x) se superpone con el Hifil (#5) pero usa la forma Qal. ''El jefe de la guardia encomendó a José'' (Gn 40:4), ''Designa a los levitas sobre el tabernáculo'' (Nm 3:10), ''Nombrad oficiales sobre el ejército'' (Dt 20:9). Árabe أَوْصَى (encargar, mandar).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128202, 'spa', 'Nifal: faltar, estar ausente', 'Nifal ''faltar, estar ausente'' (14x) nota la ausencia. ''No faltó ninguno de nosotros'' (Nm 31:49), ''Faltará una tribu de Israel'' (Jue 21:3), ''Serás echado de menos, porque tu asiento estará vacío'' (1 S 20:6, 18, 25). Árabe يُفْقَد (ser perdido/faltar), coreano 빠지다 (faltar). El Nifal pasivo expresa la carencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128211, 'spa', 'Nifal: ser visitado, castigado', 'Nifal ''ser visitado, ser castigado'' (8x) marca la recepción pasiva de la atención divina (positiva o negativa). ''Si son visitados como se visita a todo hombre'' (Nm 16:29, rebelión de Coré), ''¿Quién puede subsistir cuando es visitado?'' (Pr 19:23). Árabe يُفْتَقَد (pasivo de visitar), coreano 벌받다 (ser castigado).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128218, 'spa', 'oficial, supervisor', 'Participio pasivo Qal ''oficial, supervisor'' (5x) usado sustantivamente. ''Los oficiales de las fuerzas'' (Nm 31:14, 48), ''los capitanes y oficiales'' (2 R 11:15; 2 Cr 23:14). Árabe وُكَلاء/قُوَّاد (oficiales/comandantes), coreano 지휘관 (comandante). Quienes son designados para atender a soldados u obreros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128229, 'spa', 'echar de menos, buscar', 'Qal ''echar de menos, buscar, añorar'' (6x) describe la ausencia emocional. ''Mira si los jóvenes están bien y trae noticias'' (1 S 17:18, lit. ''atiende a su bienestar''), ''De seguro me echará de menos'' (1 S 20:6), ''No os ocupéis de ella'' (2 R 9:34, lit. ''no atendáis a ella''). La atención volcada en lo ausente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128247, 'spa', 'Hifil: depositar, encomendar', 'Hifil ''depositar, encomendar, confiar'' (7x) implica colocar algo al cuidado de otro. Roboam ''depositó los escudos con los guardias'' (1 R 14:27; 2 Cr 12:10), Giezi ''depositó los sacos en la casa'' (2 R 5:24), ''En tu mano encomiendo mi espíritu'' (Sal 31:5). Árabe أَوْدَعَ (depositar), coreano 맡기다 (confiar).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128289, 'spa', 'pasar revista (divino)', 'Dios ''pasando revista a los ejércitos para la batalla'' (Is 13:4, 1x). Aparición única del participio describiendo a Dios como quien reúne ejércitos celestiales y terrenales para el juicio. Se superpone con la acepción #3 (contar/revistar) pero con sujeto divino y contexto escatológico militar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128299, 'spa', 'ser privado', '''Soy privado del resto de mis años'' (Is 38:10, 1x, lamento de Ezequías). La única aparición sugiere ''he sido visitado con pérdida'' o ''mis años me han sido arrebatados''. La acepción conecta con #6 (faltar) pero como queja teológica sobre la muerte prematura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128334, 'spa', 'Registro contable', 'Éxodo 38:21 abre con «Estas son las cuentas del tabernáculo», seguido de un recuento exhaustivo de metales preciosos. Las glosas multilingües (accounts, cálculos) reflejan el sentido administrativo y de rendición de cuentas. La frase constructa «cuentas del tabernáculo» introduce la verificación por parte de Moisés de todos los materiales recolectados y utilizados, demostrando transparencia y responsabilidad en el manejo de las ofrendas del pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128335, 'spa', 'La dimensión punitiva de la visitación divina', 'La dimensión punitiva de la visitación divina: el ajuste de cuentas, juicio o retribución que Dios inflige sobre personas o naciones a causa del pecado. Predomina en los profetas, especialmente en la fórmula de Jeremías «en el tiempo/año de su visitación» (Jer 8:12; 10:15; 23:12). Las glosas multilingües convergen nítidamente en el concepto de castigo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128336, 'spa', 'Puesto designado de supervisión o responsabilidad administrativa, el oficio o ca', 'Puesto designado de supervisión o responsabilidad administrativa, el oficio o cargo de vigilar algo. Central en Números 3-4, donde Eleazar tiene la supervisión del santuario, y en 2 Reyes 11:18 y 2 Crónicas 23:18 para los cargos del templo. Indica un rol institucional y no una acción divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128338, 'spa', 'La acción de contar, registrar o alistar personas para un servicio organizado, u', 'La acción de contar, registrar o alistar personas para un servicio organizado, un censo o padrón. Se encuentra exclusivamente en Crónicas (1 Cr 23:11; 24:3, 19; 2 Cr 17:14; 26:11) en relación con la organización levítica y militar. Se distingue del cargo de supervisión del sentido 2.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128344, 'spa', 'El cuidado vigilante y la atención providencial de Dios, contraparte positiva de', 'El cuidado vigilante y la atención providencial de Dios, contraparte positiva de la visitación punitiva. Atestiguado solo en Job 10:12, donde Job reconoce que la פְּקֻדָּה de Dios le concedió vida y favor. Señala protección amorosa en lugar de juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128350, 'spa', 'Lugar de confinamiento o custodia, concretamente una prisión', 'Lugar de confinamiento o custodia, concretamente una prisión. Aparece en Jeremías 52:11, donde Sedequías es puesto en la casa de פְּקֻדָּה hasta su muerte. Es una extensión metonímica de «lugar bajo custodia» a «cárcel».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128354, 'spa', 'Algo depositado o almacenado para su custodia, riqueza o provisiones confiadas', 'Algo depositado o almacenado para su custodia, riqueza o provisiones confiadas. Se halla en Isaías 15:7, donde el acopio acumulado de Moab es llevado al otro lado del Torrente de los Sauces. Extiende el sentido de «confiar al cargo de alguien» al ámbito material.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128356, 'spa', 'depósito en custodia', 'Algo depositado para almacenamiento o confiado en custodia. Génesis 41:36 ordena almacenar grano ''como reserva (לְפִקָּדוֹן) para la tierra contra los siete años de hambre''—provisiones guardadas para necesidad futura. Levítico 6:2 (5:21 hebreo) aborda el engaño ''sobre un depósito (בְּפִקָּדוֹן) o una garantía''—propiedad confiada al cuidado de otro. El versículo 4 (5:23 hebreo) requiere devolver ''el depósito (הַפִּקָּדוֹן)'' con restitución completa más un quinto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128357, 'spa', 'Guardia militar', 'En Jeremías 37:13, la expresión ''capitán de la guardia'' (literalmente ''señor de la vigilancia'') identifica a Irías hijo de Selemías, quien arrestó a Jeremías en la puerta de la ciudad. Este oficial comandaba la vigilancia en la puerta de Benjamín durante el asedio, encargado de impedir deserciones, una preocupación grave dada la situación desesperada de Jerusalén.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128359, 'spa', 'Preceptos divinos o mandatos designados que aparecen casi exclusivamente en los ', 'Preceptos divinos o mandatos designados que aparecen casi exclusivamente en los Salmos (especialmente el Salmo 119). La raíz paqad (''atender, designar'') transmite instrucciones específicamente comisionadas por Dios. El Salmo 19:8 los declara ''rectos, que alegran el corazón''; el Salmo 103:18 los empareja con la fidelidad al pacto; el Salmo 111:7 afirma que son ''fieles y rectos''. Siempre aparecen en plural, subrayando la totalidad del mandato divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128365, 'spa', 'Abrir los ojos (activo) — Sentido activo de abrir los ojos, usado en diversas in', 'Abrir los ojos (activo) — Sentido activo de abrir los ojos, usado en diversas inflexiones del Qal incluyendo imperativos, perfectos, imperfectos, infinitivos y participios. Abarca tanto la vista física como la percepción espiritual: Dios abre los ojos de Agar hacia un pozo de agua (Gn 21:19), el siervo de Eliseo ve carros de fuego (2 Re 6:17), y el SEÑOR es alabado como quien ''abre los ojos de los ciegos'' (Sal 146:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128370, 'spa', 'Ojos ser abiertos (pasivo/estativo) — Sentido pasivo o estativo expresado en for', 'Ojos ser abiertos (pasivo/estativo) — Sentido pasivo o estativo expresado en formas Nifal y participio pasivo Qal, describiendo los ojos siendo abiertos o estando abiertos. Teológicamente significativo en la Caída — ''los ojos de ambos fueron abiertos'' (Gn 3:7) — y en la esperanza mesiánica — ''los ojos de los ciegos serán abiertos'' (Is 35:5). Marca momentos de transformación radical de la percepción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128381, 'spa', 'Pécaj (nombre propio)', 'El nombre personal del hijo de Remalías que usurpó el trono de Israel asesinando a Pecajías (2 R 15:25). Su reinado de veinte años está dominado por la coalición siro-efraimita contra Judá (2 R 15:27–32; Is 7:1). Las transliteraciones varían entre ''Pécaj'' y ''Peqaj'', reflejando la letra hebrea qof.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128386, 'spa', 'Nombre personal', 'Nombre personal del rey de Israel, hijo de Manahem, quien reinó dos años antes de su asesinato. 2 Reyes 15:22 introduce su reinado: ''Pecajías (פְּקַחְיָה) su hijo reinó en su lugar.'' El versículo 23 fecha su ascensión y nota que ''hizo lo malo ante los ojos de Yahveh.'' El versículo 26 registra su asesinato: ''Peka hijo de Remalías, su capitán, conspiró contra él y lo derribó en Samaria...y mató a Pecajías.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128388, 'spa', 'Supervisor, oficial designado — persona formalmente nombrada para supervisar, ge', 'Supervisor, oficial designado — persona formalmente nombrada para supervisar, gestionar o hacerse cargo de una tarea, grupo o institución específica. El sustantivo conlleva el peso de la autoridad delegada — el supervisor actúa en nombre de un poder superior, ya sea el Faraón (Gn 41:34), un rey (Est 2:3) o el sacerdocio (Jer 20:1; 2 Cr 24:11). Se construye con עַל para especificar el ámbito de supervisión (soldados, 2 Re 25:19; benjaminitas, Neh 11:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128400, 'spa', 'ornamentos tallados', 'Tallados ornamentales con forma de calabazas o protuberancias, decorando el templo de Salomón. 1 Reyes 6:18 describe el revestimiento interior de cedro: ''tallado en forma de calabazas (פְקָעִים) y flores abiertas''—obra decorativa en relieve. 1 Reyes 7:24 menciona dos veces ornamentos en el gran mar de bronce: ''bajo su borde había calabazas (פְקָעִים) rodeándolo...las calabazas (הַפְּקָעִים) estaban en dos filas, fundidas con él cuando fue fundido.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128401, 'spa', 'Calabazas silvestres tóxicas', 'En 2 Reyes 4:39, estas ''calabazas del campo'' fueron recogidas inadvertidamente durante una hambruna y añadidas a un guiso comunitario, casi causando una tragedia. La expresión destaca su naturaleza silvestre y no cultivada. La coloquíntida se asemeja a pepinos comestibles, pero contiene compuestos tóxicos que provocan graves trastornos intestinales, lo que subraya el peligro de confundir plantas silvestres en tiempos de escasez.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128402, 'spa', 'novillo, becerro', 'Un novillo joven seleccionado para sacrificio y ofrenda — la acepción primaria y abrumadoramente dominante con 130 apariciones. Usado en holocaustos (Ex 29:1), ofrendas por el pecado (Lv 4:3; Ex 29:36), ofrendas de paz (Ex 24:5) y liturgias de festividades (Nm 28-29). Español novillo y toro, francés taureau y alemán Stier convergen en el mismo referente bovino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128414, 'spa', 'toro (figurado, poderoso)', 'Los toros como imagen figurada de enemigos poderosos y agresivos o guerreros temibles. Los ''toros de Basán'' rodean al salmista en oración angustiada (Sal 22:12), evocando el ganado famosamente bien alimentado de esa región fértil como metáfora de opresores brutales. Jeremías aplica la imagen a los guerreros condenados de Babilonia: ''degollad todos sus toros'' (Jr 50:27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128427, 'spa', 'Fructificar con ironía', 'Oseas 13:15 emplea un juego de palabras deliberado: ''Aunque él (Efraín) fructifique entre los hermanos, vendrá el viento del este.'' El profeta invoca el significado del nombre Efraín (''fecundo'') solo para anunciar su reversión mediante el juicio divino. El versículo continúa con imágenes de sequía —fuentes que se secan, tesoros saqueados— transformando la bendición en desolación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128428, 'spa', 'Asno salvaje', 'El asno salvaje u onagro (פֶּרֶא, pere), un veloz e indomable équido de la estepa desértica. Funciona como símbolo poderoso: Ismael es llamado «asno montés de hombre» (Gn 16:12), identificándolo como nómada libre. En la literatura sapiencial ilustra el instinto y la satisfacción (Job 6:5), la naturaleza indomable (Job 11:12) y la provisión soberana de Dios para las criaturas silvestres (Job 39:5). Oseas y Jeremías lo emplean como metáfora de rebeldía espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128434, 'spa', 'Rey de Jarmut', 'Josué 10:3 identifica a Piram como rey de Jarmut, mencionándolo tercero entre la alianza de cinco reyes. Jarmut ha sido identificada con la actual Khirbet Yarmuk, ubicada estratégicamente en las colinas de Judea. La participación de Piram en esta coalición malograda representa la resistencia cananea organizada contra la entrada de Israel en la tierra prometida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128435, 'spa', 'Estructura del lado occidental', 'Una característica arquitectónica o área en el lado occidental del templo, de significado incierto. 2 Reyes 23:11 ubica caballos dedicados al sol ''en los recintos (בַּפַּרְוָרִים), a la entrada de la casa de Yahvé''—Josías destruyó estos elementos idólatras. 1 Crónicas 26:18 asigna porteros levitas: ''para el Parbar (לַפַּרְבָּר) al occidente, cuatro en el camino, dos en el Parbar (לַפַּרְבָּר).'' Se proponen interpretaciones como columnata o pabellón abierto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128436, 'spa', 'Hifil causativo', 'Hifil causativo: un agente divide o separa activamente a otros. Dt 32:8 recuerda cuando el Altísimo ''separó a los hijos de Adán''; Pr 16:28 advierte que el chismoso ''separa a los mejores amigos''. Rut 1:17 invoca la muerte como la única fuerza capaz de ''separar'' a Rut de Noemí, elevando el verbo al lenguaje del pacto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128437, 'spa', 'Nifal reflexivo/recíproco', 'Nifal reflexivo/recíproco: dos partes se separan o toman caminos distintos. Gn 13:9-14 narra la separación de Abram y Lot; Gn 10:5, 32 describe la división de las naciones tras el diluvio. 2 S 1:23 señala con emoción que Saúl y Jonatán ''no fueron separados'' ni en la muerte, usando la negación para resaltar una lealtad inseparable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128438, 'spa', 'Qal pasivo y Pual', 'Qal pasivo y Pual: estado de estar extendido o esparcido físicamente. Ez 1:11 describe las alas de los seres vivientes como ''extendidas'' por encima; Est 3:8 caracteriza a los judíos como ''dispersos'' entre los pueblos. La imagen espacial distingue este sentido de la separación interpersonal, enfocándose en la extensión física a través de un área.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128440, 'spa', 'Hitpael', 'Hitpael: desarticularse o dislocarse, como cuando las articulaciones se separan bajo presión. Sal 22:14 lamenta ''todos mis huesos se descoyuntan'', imagen visceral de sufrimiento. Job 41:17 pregunta si las escamas de Leviatán ''pueden separarse'', usando el mismo tema para describir una cohesión estructural que resiste el desgarro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128447, 'spa', 'Piel', 'Piel: retirarse o apartarse voluntariamente por iniciativa propia. Os 4:14 advierte contra los hombres que ''se apartan'' con prostitutas, enfatizando una separación personal deliberada de la comunidad con fines ilícitos. Este uso singular en Piel le da al tema un matiz moral ausente en las separaciones neutras del Nifal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128449, 'spa', 'Hitpael y participio Nifal', 'Hitpael y participio Nifal: ser dispersados como grupo a través del espacio. Neh 4:19 describe a los trabajadores ''dispersos'' a lo largo del muro; Sal 92:9 declara que los malhechores ''serán dispersados''. El énfasis recae en el estado resultante de amplia dispersión más que en un acto único de separación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128457, 'spa', 'Nifal de ramificación geográfica', 'Nifal de ramificación geográfica: un solo río que se divide en múltiples corrientes. Gn 2:10 registra que un río ''salía de Edén'' y allí ''se dividía'' en cuatro brazos. Este sentido concreto y espacial puede ser la metáfora raíz de la cual se desarrollaron los sentidos interpersonales y abstractos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128459, 'spa', 'Mulo — el mulo (פֶּרֶד), un híbrido de caballo y burro valorado por su paso segu', 'Mulo — el mulo (פֶּרֶד), un híbrido de caballo y burro valorado por su paso seguro y resistencia. Las glosas multilingües convergen estrechamente — español ''mulo/mula'', francés ''mulet'', alemán ''Maultiere'' — confirmando un único referente zoológico. Las asociaciones reales dominan: los príncipes montan mulos (2 Sam 13:29; 18:9), los reyes los reciben como regalos (1 Re 10:25) y sirven como bestias de carga en el comercio y el regreso del exilio (Esd 2:66; Neh 7:68).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128468, 'spa', 'Mula real de coronación', 'Una mula hembra, específicamente la mula real montada durante la coronación de Salomón. 1 Reyes 1:33 registra el mandato de David: ''haced montar a Salomón mi hijo en mi propia mula (הַפִּרְדָּה)'' hasta Gihón para la unción. El versículo 38 narra el cumplimiento: ''hicieron montar a Salomón en la mula del rey David (פִּרְדַּת הַמֶּלֶךְ דָּוִד).'' El versículo 44 informa: ''lo han hecho montar en la mula del rey (הַפִּרְדָּה).'' La repetición enfatiza legitimidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128469, 'spa', 'Semillas marchitas', 'Joel 1:17 describe las semillas marchitándose ''bajo sus terrones'', enfatizando la muerte de la simiente almacenada o enterrada. El versículo continúa la imaginería de la plaga de langostas con vocabulario agrícola: graneros arruinados, almacenes derribados, grano reseco. La destrucción de la semilla representa la pérdida de toda esperanza futura de cosecha, simbolizando el juicio divino completo sobre la tierra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128470, 'spa', 'Parque o huerto cerrado', 'Un parque cerrado, huerto o reserva, a menudo real, que contiene árboles y plantas cultivadas. Este préstamo persa (de pairi-daêza, ''recinto'') aparece en Nehemías 2:8: ''una carta a Asaf, guarda del bosque del rey (פַּרְדֵּס הַמֶּלֶךְ)'' solicitando madera. Eclesiastés 2:5: ''Hice huertos y parques (פַּרְדֵּסִים)'' con toda clase de árboles frutales. Cantar de los Cantares 4:13 lo usa figuradamente: ''Tus renuevos son un paraíso (פַּרְדֵּס) de granados.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128471, 'spa', 'El sentido Qal abarca la fecundidad natural', 'El sentido Qal abarca la fecundidad natural: dar fruto, ser productivo en descendencia o cosecha. Comprende el mandato de la creación (Gn 1:22, 28), la renovación posterior al diluvio (Gn 8:17; 9:1, 7), la multiplicación de Israel en Egipto (Éx 1:7) e imágenes proféticas de un renuevo fructífero (Is 11:1). El participio describe a una vid o persona como inherentemente fecunda (Ez 19:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128475, 'spa', 'El Hifil causativo denota el acto soberano de Dios de hacer fructífero a alguien', 'El Hifil causativo denota el acto soberano de Dios de hacer fructífero a alguien, siempre con la deidad como sujeto. Aparece exclusivamente en contextos de pacto y bendición: Abraham (Gn 17:6), Ismael (Gn 17:20), Jacob en Betel (Gn 28:3; 48:4) y el nombre de Efraín dado por José: ''Dios me hizo fructificar'' (Gn 41:52).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128491, 'spa', 'Hembra bovina, ya sea una vaca madura o una novilla joven', 'Hembra bovina, ya sea una vaca madura o una novilla joven. El término abarca contextos agrícolas, rituales, simbólicos y proféticos. En la agricultura, las vacas aparecen entre regalos de ganado (Gn 32:15) y como animales de trabajo (1 S 6:7, 10, 12, 14). En el ritual, la vaca roja de Números 19:2-10 tiene un significado purificador único. Simbólicamente, las vacas del sueño de Faraón representan ciclos económicos (Gn 41:2-26). Amós llama a las mujeres de Samaria ''vacas de Basán'' (Am 4:1), y Oseas compara a Israel con una novilla rebelde (Os 4:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128499, 'spa', 'Ciudad benjaminita', 'Josué 18:23 enumera הַפָּרָה (con artículo definido) entre doce ciudades benjaminitas del segundo distrito, junto a Ofra, Quefar-amoní, Ofni y Geba. Las versiones antiguas muestran incertidumbre sobre la ubicación incluso en la antigüedad. La herencia de Benjamín, aunque geográficamente pequeña, ocupaba una posición estratégica entre los principales territorios tribales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128500, 'spa', 'Topos o ratas-topo', 'En Isaías 2:20 se vislumbra el día en que los hombres reconocerán la inutilidad de sus ídolos, arrojándolos a lugares oscuros habitados por topos y murciélagos. La dificultad textual refleja confusión escribal, pero el punto teológico permanece claro: la orgullosa idolatría humana terminará en vergüenza, con los metales preciosos abandonados en las tinieblas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128503, 'spa', 'Nombre personal', '1 Reyes 4:17 identifica a «Josafat hijo de Parúa» como administrador «en Isacar», parte del sofisticado sistema burocrático de Salomón que dividía Israel en doce distritos tributarios y de provisiones. Esta estructura administrativa, aunque demostraba la capacidad organizativa de Salomón, también sentó las bases para el descontento que eventualmente dividiría el reino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128504, 'spa', 'Fuente de oro', '2 Crónicas 3:6 declara que Salomón «revistió la casa de piedras preciosas para ornamento, y el oro era oro de Parvaim», destacando su calidad excepcional. Se debate si el nombre designa una región minera específica o es un término más general para oro refinado. La atención del Cronista a las fuentes materiales refleja la convicción teológica de que solo lo mejor es digno de la presencia divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128505, 'spa', 'Olla para cocinar', 'Una olla o vasija para cocinar usada para hervir alimentos, probablemente de barro. Números 11:8 describe la preparación del maná: ''lo molían en molinos...y lo hervían en la olla (בַּפָּרוּר).'' Jueces 6:19 tiene a Gedeón traer provisiones al ángel: ''la carne la puso en una canasta, y el caldo lo puso en la olla (נָתַן בַּפָּרוּר).'' 1 Samuel 2:14 describe al criado del sacerdote metiendo su tenedor ''en la sartén o caldero (בַּפָּרוּר).''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128507, 'spa', 'aldeas sin muros', 'Aldeas sin muros, asentamientos abiertos o zonas rurales sin fortificaciones. Ester 9:19 distingue a ''los judíos que viven en las aldeas sin muros (עָרֵי הַפְּרָזוֹת)'' de aquellos en Susa—afectando las fechas de celebración de Purim. Ezequiel 38:11 describe el objetivo de Gog: ''tierra de aldeas sin muros (אֶרֶץ פְּרָזוֹת)...habitando seguramente, todos ellos sin muros.'' Zacarías 2:4 (versículo 8 en hebreo) promete que Jerusalén será habitada sin murallas por su abundante población y protección divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128509, 'spa', 'Aldeano o campesino', 'Deuteronomio 3:5 opone ''asentamientos rurales'' a ''ciudades fortificadas con altos muros''. 1 Samuel 6:18 menciona tanto ciudades fortificadas como aldeas abiertas afectadas por la plaga. Ester 9:19 hace referencia dos veces a los judíos rurales (lectura Qeré הַפְּרָזִים frente a Ketiv הפרוזים) que celebran el Purim de manera distinta a los habitantes urbanos. El español ''aldeanos'' y el francés ''campo abierto'' captan bien el carácter rural y sin protección.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128510, 'spa', 'Gentilicio para los ferezeos, un pueblo preisraelita en Canaán', 'Gentilicio para los ferezeos, un pueblo preisraelita en Canaán. Se encuentra principalmente en las listas formulaicas de desposesión (Éx 3:8; Dt 7:1; Jos 3:10; 24:11). Menciones narrativas independientes: Gn 13:7 (habitando junto al cananeo) y Gn 34:30 (el temor de Jacob tras el incidente de Siquem). Posiblemente derivado de פְּרָזָה (''asentamiento sin murallas''). Las traducciones preservan fielmente el nombre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128522, 'spa', 'Hierro (metal) — Hierro como metal físico y sustancia simbólica, presente exclus', 'Hierro (metal) — Hierro como metal físico y sustancia simbólica, presente exclusivamente en las porciones arameas de Daniel. Usado literalmente para el material de las piernas y pies de la estatua en el sueño de Nabucodonosor (Dn 2:33-45), para la banda de hierro sobre el árbol cortado (Dn 4:12, 20), para los vasos del banquete de Belsasar (Dn 5:4, 23), y para los dientes devoradores de la cuarta bestia (Dn 7:7, 19). El metal simboliza consistentemente el poder imperial aplastante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128525, 'spa', 'Florecimiento figurado de personas o realidades abstractas, extendiendo la image', 'Florecimiento figurado de personas o realidades abstractas, extendiendo la imagen botánica a la prosperidad humana. El justo florece como la palmera (Sal 92:12), y en la era mesiánica la justicia prospera (Sal 72:7). Proverbios 11:28 y 14:11 lo aplican al hogar de los rectos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128526, 'spa', 'Qal intransitivo', 'Qal intransitivo: echar brotes, retoñar o florecer en sentido botánico literal. La vara de Aarón que brotó (Nm 17:5, 8), la vid que retoña en el sueño del copero del faraón (Gn 40:10) y el florecer de los jardines del Cantar de los Cantares (Cnt 6:11; 7:13) emplean este sentido concreto de emergencia vegetal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128532, 'spa', 'Hifil causativo', 'Hifil causativo: hacer que algo brote o florezca, con Dios como agente habitual. En Ezequiel 17:24 el Señor abate al árbol elevado y hace florecer al árbol seco. Isaías 17:11 advierte que incluso lo que uno hace florecer puede perderse. La voz causativa subraya la agencia divina o humana detrás del florecimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128549, 'spa', 'Brotar (enfermedad cutánea)', 'Brotar, erupcionar o extenderse sobre la piel, referido a enfermedades y afecciones cutáneas en los textos sacerdotales. En Éxodo 9:9-10, los forúnculos ''brotan'' sobre los egipcios y su ganado durante la sexta plaga. Las demás ocurrencias en Levítico 13:12, 20, 25, 39, 42, 57 y 14:43 describen la צָרַעַת (tradicionalmente ''lepra'') extendiéndose por la piel, lo cual el sacerdote debía examinar para determinar la pureza ritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128555, 'spa', 'Flor, capullo — Flor, capullo o brote, usado tanto literalmente como en imágenes', 'Flor, capullo — Flor, capullo o brote, usado tanto literalmente como en imágenes decorativas o metafóricas. La mayoría de las ocurrencias describen los ornamentos florales de almendro en la menorá del tabernáculo (Éx 25:31-34; 37:17-20; Nm 8:4), donde el término denota las decoraciones florales en forma de copa. La vara de Aarón produce brotes y flores como señal de elección divina (Nm 17:23). Metafóricamente, Is 5:24 y 18:5 lo usan para la fugacidad de la gloria humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128565, 'spa', 'Chusma despreciable', 'Job 30:12 emplea este término en una secuencia de acciones hostiles: «A mi diestra se levanta la chusma; empujan mis pies y preparan contra mí caminos de destrucción.» La retórica de Job subraya una inversión de estatus: quienes debían honrarlo lo tratan con desprecio. El término capta la indignación de ser atacado por aquellos a quienes la sociedad misma despreciaba.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128566, 'spa', 'Improvisación frívola', 'Amós 6:5 retrata a ricos ociosos ''improvisando al arpa'', en paralelo con la composición de David pero carentes de su seriedad. Las glosas multilingües varían (improvisar, cantar, rasguear), reflejando la dificultad textual. El punto profético es la frivolidad de su música: entretenimiento egoísta mientras ignoran la ruina de José.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128567, 'spa', 'Uvas caídas', 'Levítico 19:10 ordena: ''No rebuscarás tu viña ni recogerás las uvas caídas; las dejarás para el pobre y el extranjero.'' Las glosas multilingües (uva caída, fruto caído) identifican consistentemente estos restos de la cosecha. Esta ley es paralela al mandato de dejar espigas en los campos de grano, y forma parte de un amplio código de justicia social.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128568, 'spa', 'fruto, producto agrícola', 'El sentido literal y concreto que abarca todo producto agrícola: fruto de árboles (Gn 1:11-12; 3:2), fruto de la vid (2 R 19:29; Is 65:21) y fruto de la tierra (Gn 4:3; Dt 7:13). Esta acepción representa la gran mayoría de las apariciones y se encuentra en casi toda combinación de cadena constructa. Español fruto, francés fruit y alemán Frucht siguen este significado primario sin dificultad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128586, 'spa', 'fructífero, que da fruto', 'Un uso adjetival-atributivo en la cadena constructa עֵץ פְּרִי (''árbol frutal'' o ''árbol que da fruto''), donde פְּרִי modifica al sustantivo en lugar de funcionar como sustantivo independiente. Salmo 107:34 ofrece el único caso claro. Español fructífera capta este desplazamiento de sustantivo a calificador, distinguiéndolo del sentido sustantivo autónomo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128588, 'spa', 'descendencia, progenie', 'La extensión metafórica a la descendencia y los hijos, como en ''fruto del vientre'' y ''fruto del cuerpo'' (Sal 21:10). Esta acepción tiende un puente entre lo agrícola y lo personal, apoyándose en la imaginería orgánica de crecimiento y generación. El inglés cambia a offspring mientras español y francés conservan fruto/fruit, mostrando cómo algunas lenguas preservan la metáfora y otras lexicalizan el dominio meta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128594, 'spa', 'Violento, ladrón', 'Persona violenta e ilegal o criatura depredadora que usa la fuerza para robar, oprimir o destruir. Aplicado a agresores humanos en Sal 17:4 (hombres violentos), Jer 7:11 (ladrones que profanan el Templo), Ez 7:22 (profanadores), Ez 18:10 (opresor sanguinario) y Dan 11:14 (rebeldes violentos). Is 35:9 lo aplica a una bestia rapaz, uniendo violencia humana y animal bajo un mismo término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128600, 'spa', 'Dureza, severidad', 'Dureza, severidad o crueldad en el ejercicio del poder sobre las personas, siempre en la frase be-farekh (''con dureza''). Éx 1:13-14 describe la opresión egipcia sobre Israel; Lv 25:43, 46, 53 prohíben a los israelitas gobernar así a sus compatriotas; Ez 34:4 condena a los pastores de Israel por la misma crueldad. El español ''rigor'' y ''dureza'' captan fielmente este campo semántico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128602, 'spa', 'La cortina interior del tabernáculo y del templo que separaba el Lugar Santo del', 'La cortina interior del tabernáculo y del templo que separaba el Lugar Santo del Lugar Santísimo, la partición más sagrada del culto israelita. Hecha de hilo azul, púrpura y escarlata con querubines bordados (Éx 26:31-33), protegía el arca y el propiciatorio del acceso sacerdotal ordinario. Llamada paroketh hammasakh (''velo de la cubierta'', Éx 35:12; 40:21) y paroketh haqqodesh (''velo del santuario'', Lv 4:6). Solo el sumo sacerdote podía traspasarlo, una vez al año en el Día de la Expiación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128607, 'spa', 'rasgar vestiduras', 'Rasgar o romper vestiduras, usado en legislación sacerdotal sobre costumbres de duelo. Levítico 10:6 prohíbe a Aarón y sus hijos: ''No rasguéis (תִּפְרֹ֑מוּ) vuestras vestiduras, no sea que muráis''—después de las muertes de Nadab y Abiú, los sacerdotes deben mantener integridad ritual. Levítico 13:45 requiere que el leproso tenga ''sus vestiduras rasgadas (פְּרֻמִים)''—identificación visible de impureza. Levítico 21:10 prohíbe al sumo sacerdote rasgar sus vestiduras incluso en duelo por familiares cercanos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128608, 'spa', 'Nombre propio persa', 'Ester 9:9 enumera a Parmasta como el séptimo de los diez hijos de Amán: ''Parsandata, Dalfón, Aspata, Porata, Adalía, Aridata, Parmasta, Arisai, Aridai y Vaizata.'' Las glosas multilingües preservan el nombre mediante transliteración. La lista estilizada de los diez nombres, junto con su ejecución colectiva, subraya la justicia completa: la erradicación del linaje de Amán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128609, 'spa', 'Nombre propio', 'Números 34:25 identifica ''al líder de la tribu de los hijos de Zabulón, Elizafán hijo de Parnac'', incluyéndolo entre los diez representantes tribales designados para la división de la tierra. Las glosas multilingües preservan el nombre propio. Este nombramiento administrativo enfatizaba la transparencia y la representación tribal en la tarea crucial de la asignación de herencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128610, 'spa', 'Dividir, hender (pezuñas) — Hifil', 'Dividir, hender (pezuñas) — Hifil. Hifil: dividir o hender, específicamente las pezuñas de animales en las leyes dietéticas levíticas. Levítico 11:3–7 y Deuteronomio 14:6–8 usan este verbo repetidamente para clasificar animales puros e impuros según si ''dividen la pezuña''. El causativo Hifil añade el matiz de producir una hendidura: la pezuña es causada a estar partida. Se trata de un término técnico zoológico restringido al lenguaje legislativo sobre pureza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128617, 'spa', 'Partir, repartir (pan) — Qal', 'Partir, repartir (pan) — Qal. Qal: partir o repartir, especialmente pan o alimento para el hambriento. Isaías 58:7 ordena partir (פָּרֹס) tu pan con el hambriento como verdadero ayuno. Jeremías 16:7 describe la costumbre de partir pan para los dolientes. La acción física subyacente de hender conecta ambos sentidos, pero aquí el énfasis recae no solo en romper sino en compartir generosamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128619, 'spa', 'División del reino', 'Daniel 5:28 interpreta ''PERES'' como ''tu reino ha sido dividido y entregado a los medos y los persas.'' El juego de palabras funciona en múltiples niveles: la raíz significa ''dividir'', la forma suena como ''Persia'', y el mensaje teológico es que el juicio divino ha partido el reino de Belsasar. Las glosas multilingües (dividido, briser) captan el sentido de partición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128622, 'spa', 'Nombre propio del Imperio Persa y su territorio, centrado en el actual Irán', 'Nombre propio del Imperio Persa y su territorio, centrado en el actual Irán. Todas sus apariciones pertenecen a la literatura postexílica o profética tardía. El nombre ancla el punto de inflexión teológico del fin del exilio: el decreto de Ciro (2 Cr 36:22-23; Esd 1:1-2), los dramas cortesanos de Ester bajo la ley persa (Est 1:3, 19), las visiones apocalípticas de Daniel sobre ''los reyes de Media y Persia'' (Dn 8:20; 10:13) y las listas de Ezequiel de naciones aliadas (Ez 27:10; 38:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128625, 'spa', 'Persia / persas', 'El nombre propio Paras (פָּרַס) que designa a Persia o a los persas como entidad nacional e imperial. En Daniel aparece en el episodio de Belsasar (Dan 5:28) y en la frase ''ley de medos y persas'' (Dan 6:8, 12, 15). En Esdras identifica la autoridad real persa que posibilitó la reconstrucción del Templo (Esd 4:24; 6:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128627, 'spa', 'Pezuña — La cubierta dura de queratina del pie de un ungulado, ya sea hendida o ', 'Pezuña — La cubierta dura de queratina del pie de un ungulado, ya sea hendida o sólida. La mayoría de las ocurrencias aparecen en las leyes de pureza levíticas (Lv 11; Dt 14), donde la pezuña hendida es un criterio de pureza ritual. También se usa para las pezuñas de los caballos (Is 5:28; Jer 47:3) y figuradamente de Sion pisoteando a sus enemigos (Mi 4:13). Un único referente concreto a lo largo de las 21 apariciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128636, 'spa', 'El persa', 'Nehemías 12:22 declara: «En los días de Eliasib, Joiada, Johanán y Jadúa, los jefes de familias fueron registrados, así como los sacerdotes en el reinado de Darío el persa.» El artículo definido «el persa» distingue a este Darío de reyes anteriores. Las glosas multilingües conservan el gentilicio con artículo. Esta nota genealógica documenta la continuidad del sacerdocio durante la dominación persa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128638, 'spa', 'Soltar o desatar', 'Jueces 5:2 comienza: «Cuando [los líderes guiaron / el cabello se soltó / los guerreros se consagraron] en Israel, cuando el pueblo se ofreció voluntariamente, ¡bendigan al SEÑOR!» Las glosas multilingües tienden al sentido de «desatar». El contexto sugiere dedicación guerrera o movilización: la respuesta voluntaria del pueblo al llamado de Débora y Barac ante la opresión cananea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128639, 'spa', 'Descuidar, ignorar, rechazar', 'Descuidar, ignorar, rechazar. Desatender, desechar o rechazar la instrucción y el consejo. Proverbios emplea este sentido cuatro veces como antítesis sapiencial: quien ''rechaza'' (פּוֹרֵעַ) la corrección se desprecia a sí mismo (Pr 15:32). Las traducciones al español como ''rechaza'' y al francés como ''abandonner'' destacan el alejamiento deliberado de la guía autoritativa, no mero olvido sino rechazo activo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128640, 'spa', 'Soltar, dejar sin freno', 'Soltar, dejar sin freno. Dejar a las personas sin control, removiendo toda restricción para que se vuelvan indisciplinadas y disolutos. La escena de Éxodo 32:25 usa esta raíz dos veces: Aarón los ''había soltado'' y estaban ''desenfrenados'', activa y pasiva de la misma imagen. Proverbios 29:18 lo extiende proverbialmente: donde no hay visión, el pueblo ''se desenfrena''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128641, 'spa', 'Descubrir, desatar, soltar', 'Descubrir, desatar, soltar. Descubrir o soltar físicamente, especialmente el cabello o la cabeza. En la legislación sacerdotal el sacerdote ''suelta'' el cabello de la mujer sospechosa (Nm 5:18), y el leproso debe dejar su cabeza ''descubierta'' (Lv 13:45). Este sentido concreto y corporal se refiere a quitar una cobertura o atadura, frecuentemente en contextos rituales o de duelo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128643, 'spa', 'Hifil', 'Hifil: hacer cesar, estorbar. Hifil causativo: hacer que las personas cesen o desistan de su trabajo, impidiendo su tarea. Faraón acusa a Moisés y Aarón en Éxodo 5:4 de hacer que los israelitas ''descansen'' de sus cargas. El matiz es de cesación forzada impuesta por un agente externo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128644, 'spa', 'Hifil', 'Hifil: causar desorden. Hifil causativo: causar desenfreno o colapso moral al remover la autoridad. En 2 Crónicas 28:19 el rey Acaz ''hizo que Judá actuara desenfrenadamente'', una única atestiguación donde el tema causativo intensifica la imagen Qal de un pueblo sin freno, convirtiéndola en instigación activa del caos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128647, 'spa', 'Evitar, abstenerse', 'Evitar, abstenerse. Evitar o abstenerse deliberadamente de algo dañino. En Proverbios 4:15 el sabio ordena ''evítalo, pasa de largo'', y Ezequiel 24:14 emplea una fuerza similar para la resolución divina. Este sentido implica contenerse o apartarse deliberadamente, no simple negligencia pasiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128655, 'spa', 'Faraón', 'El título real egipcio (del egipcio pr-ꜥꜣ, ''casa grande'') usado como nombre propio para el rey de Egipto a lo largo de todos los períodos bíblicos. Identifica a los monarcas de las narraciones patriarcales (Gn 12:15), al opresor del Éxodo (Ex 5-14), aliados políticos de los reyes israelitas (1 R 3:1) y blancos del juicio profético (Ez 29:2-3). Transliterado de manera uniforme en todas las lenguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128665, 'spa', 'Faraón Necao (nombre propio)', 'Nombre propio compuesto Faraón Necao (פַּרְעֹה נְכוֹ / נְכֹה), que identifica a Necao II de la dinastía XXVI de Egipto. Es históricamente relevante por matar a Josías en Meguido (2 R 23:29; 2 Cr 35:20-22), imponer tributo y deponer a Joacaz en favor de Joacim (2 R 23:33-35; 2 Cr 36:4), y ser posteriormente derrotado en Carquemis por Nabucodonosor (Jer 46:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128670, 'spa', 'Nombre propio Paros', 'El nombre propio Paros (פַּרְעֹשׁ, ''pulga''), que designa al ancestro de una importante familia postexílica. La LXX lo traduce como Φορος y Φαρες. La familia aparece en las listas de retorno (Esd 2:3; Neh 7:8), la caravana de Esdras (Esd 8:3), la crisis de esposas extranjeras (Esd 10:25), la reconstrucción del muro (Neh 3:25) y el sellado del pacto (Neh 10:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128671, 'spa', 'Ciudad de Efraín', 'Jueces 12:15 registra que Abdón hijo de Hilel «murió y fue sepultado en Piratón, en la tierra de Efraín, en la montaña de los amalecitas.» Las glosas multilingües preservan el topónimo con transliteración estándar. La mención de «la montaña de los amalecitas» resulta intrigante, sugiriendo una antigua presencia amalecita en esta región efraimita o un nombre geográfico heredado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128672, 'spa', 'Gentilicio de Piratón', 'Adjetivo gentilicio que indica procedencia de Piratón en Efraín. Se aplica al juez Abdón hijo de Hilel (Jue 12:13, 15) y a Benaía entre los guerreros selectos de David (2 Sam 23:30; 1 Cr 11:31; 27:14). La diferencia ortográfica entre פִּרְעָתֹנִי en Samuel y פִּרְעָתוֹנִי en Crónicas representa una variación escribal normal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128673, 'spa', 'Río de Damasco', 'En 2 Reyes 5:12 se registra la protesta de Naamán al rechazar inicialmente la sencilla prescripción de Eliseo para sanar su lepra. Los ríos Abaná y Farfar representaban los abundantes recursos hídricos de Damasco, en contraste con la apariencia menos impresionante del Jordán. El arrebato de Naamán revela el desafío de obedecer las instrucciones inesperadas de Dios con humildad y fe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128674, 'spa', 'Irrumpir, romper con fuerza violenta, ya sea abriendo brecha en una barrera físi', 'Irrumpir, romper con fuerza violenta, ya sea abriendo brecha en una barrera física, estallando en ira divina o brotando de un espacio confinado. Es la imagen raíz de la palabra, vívida en el nombre de Pérez en Gn 38:29 (''¡Qué brecha te has abierto!''). En Éx 19:22, 24 Dios amenaza con ''irrumpir'' contra quienes se acerquen al Sinaí sin autorización, y en 2 S 5:20 David nombra su victoria Baal-perazim (''Señor de las irrupciones'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128675, 'spa', 'Extenderse, multiplicarse o aumentar más allá de lo esperado, dicho de personas,', 'Extenderse, multiplicarse o aumentar más allá de lo esperado, dicho de personas, ganado e influencia que se expanden con impulso irresistible. Los rebaños de Jacob ''se extendieron en gran manera'' (Gn 30:30, 43), Israel se multiplica pese a la opresión en Egipto (Éx 1:12), y los descendientes de Jacob se esparcen hacia los cuatro puntos cardinales en la promesa de Betel (Gn 28:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128676, 'spa', 'Derribar, demoler o abrir brecha en muros y fortificaciones, con énfasis en la d', 'Derribar, demoler o abrir brecha en muros y fortificaciones, con énfasis en la destrucción de estructuras construidas. Joás derriba cuatrocientos codos del muro de Jerusalén (2 R 14:13); Dios mismo quita el ''cerco'' de su viña Israel (Sal 80:12; Is 5:5). Neh 4:3 emplea el verbo para describir los muros arruinados que un zorro podría derribar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128679, 'spa', 'Insistir con presión social, urgir encarecidamente a alguien para que acepte hos', 'Insistir con presión social, urgir encarecidamente a alguien para que acepte hospitalidad o cumpla un pedido. En 1 S 28:23 sus siervos y la mujer de Endor ''insisten'' a Saúl hasta que come; en 2 S 13:25, 27 Absalón ''insta'' a David para que deje ir a Amnón. Se trata de un sentido comunicativo e interpersonal, claramente distinto de la ruptura física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128681, 'spa', 'Estado pasivo de estar derribado, con brecha abierta o en ruinas, expresado medi', 'Estado pasivo de estar derribado, con brecha abierta o en ruinas, expresado mediante participios pasivos del Qal y el Pual. Los muros están ''derribados'' en la Jerusalén devastada de Nehemías (Neh 1:3; 2:13; 4:7), y Ezequías repara lo que estaba ''abierto'' (2 Cr 32:5). Pr 25:28 emplea la imagen de forma memorable: ''Como ciudad derribada y sin muros es el hombre que no domina su espíritu.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128697, 'spa', 'Una única aparición en 1 S 25', 'Una única aparición en 1 S 25:10 donde los hombres de David son descritos como siervos que ''se fugan'' de sus amos. El sentido sugiere una ruptura de vínculos sociales o de autoridad, aplicando la imagen de brecha propia de la raíz al ámbito de la relación amo-siervo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128716, 'spa', 'Brecha, abertura en un muro — Brecha, abertura o rotura en un muro, fortificació', 'Brecha, abertura en un muro — Brecha, abertura o rotura en un muro, fortificación o barrera protectora — la apertura estática resultado de la destrucción que requiere reparación. Sentido dominante (14 ocurrencias), abarcando uso literal y figurado: muros de ciudad rotos (1 Re 11:27; Neh 6:1; Am 4:3), un muro que se derrumba comparado con una brecha abultada (Is 30:13), brechas en la ''muralla'' de defensa nacional o espiritual que los profetas debían reparar (Ez 13:5; 22:30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128717, 'spa', 'Irrupción, estallido violento — Irrupción, estallido violento o rompimiento enér', 'Irrupción, estallido violento — Irrupción, estallido violento o rompimiento enérgico: el evento dinámico de una barrera que cede bajo presión, especialmente por poder divino. Este sentido (5 ocurrencias) se centra en la etiología del nombre Baal-perazim: ''el SEÑOR ha irrumpido contra mis enemigos delante de mí como irrupción de aguas'', por lo que David llamó al lugar ''Señor de las irrupciones'' (2 S 5:20; 1 Cr 14:11). Incluye también el nombre de Peres-uza (2 S 6:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128731, 'spa', 'Pérets / Fares (nombre propio)', 'Pérets / Fares (nombre propio). El nombre propio Pérets (פֶּרֶץ, ''brecha''), que designa al hijo de Judá y Tamar, antepasado de la línea real davídica. Nombrado así por irrumpir del vientre delante de su gemelo (Gn 38:29), encabeza el clan peresita dentro de Judá (Nm 26:20). Rut 4:12, 18 traza explícitamente la línea desde Pérets a través de Booz hasta David, consolidando su importancia genealógica en la historia de la redención.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128734, 'spa', 'Clan de Fares', 'Números 26:20 enumera los clanes de Judá: «de Sela, la familia de los selanitas; de Fares, la familia de los faresitas; de Zéraj, la familia de los zeraítas.» El artículo definido «el faresita» funciona como designación colectiva. Este censo estableció a los faresitas como un clan principal de Judá, anticipando su prominencia posterior a través de la línea davídica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128735, 'spa', 'Monte del juicio', 'Isaías 28:21 advierte que el SEÑOR se levantará como en el monte Perazim para ejecutar su obra extraña. El profeta recuerda deliberadamente las victorias pasadas de Dios a favor de Israel —en Perazim contra los filisteos, en Gabaón contra los cananeos— para intensificar la advertencia de que ahora Dios luchará contra su propio pueblo desobediente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128736, 'spa', 'Peres-uza (topónimo)', 'Las cuatro referencias apuntan al topónimo Peres-uza, donde Uza murió al tocar el arca. 2 Samuel 6:8 y su paralelo en 1 Crónicas 13:11 (cada uno mencionándolo dos veces) conmemoran esta ''brecha contra Uza''. Las glosas multilingües conservan el nombre compuesto Peres-Uza como designación geográfica asociada a ese juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128737, 'spa', 'Arrancar, quitar', 'Arrancar o quitar algo que está físicamente adherido, especialmente ornamentos, joyas o un yugo. En Éxodo 32:2-3 los israelitas arrancan sus pendientes de oro. Génesis 27:40 emplea la imagen de romper un yugo del cuello, un acto de liberación violenta de la sujeción. El verbo transmite la fuerza abrupta de la separación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128739, 'spa', 'Rescatar, librar', 'Rescatar o librar, extensión figurada en la que alguien es ''arrancado'' de las garras del opresor. Este sentido se alinea con los cognados arameos y siríacos que significan ''redimir, liberar''. El Salmo 136:24 celebra a Dios que ''nos rescató de nuestros enemigos'', y Lamentaciones 5:8 lamenta que ''no hay quien nos libre''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128741, 'spa', 'Despedazar, desgarrar', 'Desgarrar o despedazar violentamente, dicho de un depredador que destroza a su presa. El Salmo 7:2 imagina a un enemigo ''desgarrando como león'', Nahúm 2:13 describe al león despedazando para sus cachorros, y Zacarías 11:16 retrata a un pastor negligente que arranca las pezuñas de su rebaño. Evoca destrucción salvaje, pieza por pieza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128744, 'spa', 'Ser desgajado', 'Ser desgajado o roto (Hitpael reflexivo/pasivo), dicho de ramas arrancadas de una vid. Ezequiel 19:12 usa esta forma para las varas fuertes de la vid que ''fueron rotas'', extendiendo la imagen de arrancar al ámbito botánico. El resultado pasivo enfatiza la violencia de la separación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128746, 'spa', 'Ruptura moral decisiva', 'Daniel 4:27 emplea este imperativo en un consejo solemne: «Redime tus pecados con justicia». Las diversas traducciones (rompe, redime, arranca) coinciden en la idea de separación del pecado. La construcción con beth instrumental indica que la acción justa es el medio de ruptura con el mal pasado. Daniel urge al rey a un cambio radical e inmediato.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128748, 'spa', 'Lectura textual disputada', 'Isaías 65:4 (Ketiv) menciona este término problemático en una lista de prácticas abominables que Dios condena. El consenso académico favorece leer «caldo» (de una raíz diferente pero similar) para hacer paralelo con «carne de cerdo» mencionada antes en el versículo. El problema de fondo es claro: sincretismo religioso ilícito que mezcla el culto a Yahvé con rituales paganos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128749, 'spa', 'Quebrantar o violar un pacto, mandamiento o acuerdo vinculante — el sentido más ', 'Quebrantar o violar un pacto, mandamiento o acuerdo vinculante — el sentido más frecuente y teológicamente central, con 21 ocurrencias. El incircunciso «ha quebrantado mi pacto» (Gn 17:14); la desobediencia de Israel en Lv 26:15 se describe como «quebrantar» el pacto hasta invocar maldiciones. Jueces 2:1 registra la declaración de Dios: «Nunca quebrantaré mi pacto con vosotros», la asimetría divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128753, 'spa', 'Anular o invalidar un voto u obligación por decreto de autoridad — 14 ocurrencia', 'Anular o invalidar un voto u obligación por decreto de autoridad — 14 ocurrencias concentradas en la legislación sobre votos de Nm 30. Un padre puede «anular» el voto de su hija (Nm 30:5); un esposo puede «anular» el juramento de su esposa el día que lo oye (Nm 30:8, 12-13). No es transgresión sino nulificación legítima por autoridad reconocida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128756, 'spa', 'Frustrar, desbaratar o reducir a nada los planes o el consejo de otro — 7 ocurre', 'Frustrar, desbaratar o reducir a nada los planes o el consejo de otro — 7 ocurrencias en contextos sapienciales y narrativos. Husai es enviado a «frustrar el consejo de Ahitofel» (2 S 15:34; 17:14). Dios «frustra las señales de los impostores» (Is 44:25); «frustra los designios de los astutos» (Job 5:12). Proverbios 15:22 advierte que sin consejo los planes «se frustran».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128757, 'spa', 'Ser quebrantado, fracasar o quedar en nada — la dimensión pasiva e intransitiva,', 'Ser quebrantado, fracasar o quedar en nada — la dimensión pasiva e intransitiva, que cubre las formas Hofal y los usos intransitivos del Hifil (4 ocurrencias). Isaías 8:10: «Trazad un plan, pero será frustrado.» Jeremías 33:21 plantea la hipótesis de que el pacto de Dios con David fuera «quebrantado.» Zacarías 11:11 relata cómo el cayado «Gracia» fue quebrado como acto simbólico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128778, 'spa', 'Forma aislada e intensificada', 'Forma aislada e intensificada: hacer pedazos o destrozar. Job 16:12 usa la rara forma Pilpel וַיְפַרְפְּרֵנִי (''me hizo pedazos''), una reduplicación dramática que transmite una rotura violenta y repetida. Esta única ocurrencia se distingue de los demás sentidos por su matiz de destrucción física extrema; el cognado asirio parāru (''destrozar'') es el paralelo más cercano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128784, 'spa', 'partir, dividir', 'Partir, dividir o agrietar completamente, usado para división física dramática. Salmo 74:13 alaba a Dios: ''Dividiste (פּוֹרַרְתָּ) el mar con tu poder''—la liberación del Éxodo a través de aguas divididas (forma Poʿel). Isaías 24:19 describe juicio apocalíptico con formas intensivas: ''La tierra se parte completamente (פּוֹר הִתְפּוֹרְרָה), la tierra se agrieta (הִתְפּוֹרְרָה אֶרֶץ)''—enfatizando fractura total bajo juicio divino. Ambos pasajes presentan división violenta mediante acción divina soberana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128785, 'spa', 'Qal activo', 'Qal activo: extender, desplegar, tender — el sentido dominante que cubre 54 de 67 apariciones. Abarca extender las manos en oración (Éx 9:29, 33; 1 R 8:22; Esd 9:5), alas desplegadas en vuelo o cobertura (Éx 37:9; Dt 32:11; 1 R 6:27), prendas tendidas (Jue 8:25; Dt 22:17), redes extendidas para atrapar (Os 7:12; Ez 12:13) y cubiertas desplegadas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (128790, 'spa', 'Piel intensivo', 'Piel intensivo: extender de manera deliberada, enfática o exhaustiva. Las seis apariciones del Piel tienen un peso teológico especial: Isaías describe las manos de Dios extendidas todo el día hacia un pueblo rebelde (Is 65:2), y el salmista extiende sus manos en oración desesperada (Sal 143:6). La intensificación del Piel en Is 1:15 — ''cuando extendéis las manos, esconderé mis ojos'' — confiere al gesto mayor urgencia.');